{"path": "parser.mjs", "content": "const SKU_PATTERN = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_PATTERN = /^[0-9]+$/;

function parseSafeInteger(raw, fieldName, lineNumber, allowZero) {
  if (!DIGITS_PATTERN.test(raw)) {
    throw new Error(
      `Row ${lineNumber}: ${fieldName} must be base-10 digits, got "${raw}"`
    );
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(
      `Row ${lineNumber}: ${fieldName} exceeds Number.MAX_SAFE_INTEGER`
    );
  }
  if (!allowZero && value <= 0) {
    throw new Error(`Row ${lineNumber}: ${fieldName} must be positive`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }

  const orders = [];
  const lines = text.split('\n');

  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1;
    const line = lines[index].endsWith('\r')
      ? lines[index].slice(0, -1)
      : lines[index];

    if (line.trim() === '') {
      continue;
    }

    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(
        `Row ${lineNumber}: expected exactly 3 fields, got ${fields.length}`
      );
    }

    const sku = fields[0].trim();
    const quantityRaw = fields[1].trim();
    const unitPriceRaw = fields[2].trim();

    if (!SKU_PATTERN.test(sku)) {
      throw new Error(`Row ${lineNumber}: invalid SKU "${sku}"`);
    }

    const quantity = parseSafeInteger(quantityRaw, 'quantity', lineNumber, false);
    const unitPriceCents = parseSafeInteger(
      unitPriceRaw,
      'unitPriceCents',
      lineNumber,
      true
    );

    orders.push({ sku, quantity, unitPriceCents });
  }

  return orders;
}
"}

